export function buildLines(
  cwd: string,
  state: StatuslineState,
  branchLabel: string | null,
  width?: number,
  palette: Partial<StatuslinePalette> = {},
  extensionStatuses: ReadonlyMap<string, string> = new Map(),
  theme?: StatuslineTheme,
): string[] {
